VerifierFn = Callable[[ClaimRecord, Context], None]

_NORM_QUOTES = str.maketrans({'"': "״"})


def _plain_node_has_label_template(node, label_template: str) -> bool:
    """Return whether label_template appears in node as stmpl/tmpl content."""
    label_template = label_template.translate(_NORM_QUOTES)
    if isinstance(node, str):
        return node.translate(_NORM_QUOTES) == label_template
    if isinstance(node, dict):
        stmpl = node.get("stmpl")
        if isinstance(stmpl, str):
            name = stmpl.split("|", 1)[0].translate(_NORM_QUOTES)
            if name == label_template:
                return True
        for value in node.values():
            if _plain_node_has_label_template(value, label_template):
                return True
    elif isinstance(node, list):
        if len(node) == 1 and isinstance(node[0], str):
            if node[0].translate(_NORM_QUOTES) == label_template:
                return True
        for item in node:
            if _plain_node_has_label_template(item, label_template):
                return True
    return False


def _iter_plain_template_occurrences(node):
    """Yield (kind, template_name, args) for plain stmpl/tmpl template objects."""
    if isinstance(node, dict):
        if isinstance(node.get("stmpl"), str):
            parts = node["stmpl"].split("|")
            if parts:
                yield "stmpl", parts[0], parts[1:]
            return

        tmpl_tree = node.get("tmpl")
        if isinstance(tmpl_tree, list) and tmpl_tree:
            first = tmpl_tree[0]
            if isinstance(first, list) and first and isinstance(first[0], str):
                yield "tmpl", first[0], tmpl_tree[1:]
            for arg_node in tmpl_tree[1:]:
                yield from _iter_plain_template_occurrences(arg_node)
            return

        for value in node.values():
            yield from _iter_plain_template_occurrences(value)
        return

    if isinstance(node, list):
        for item in node:
            yield from _iter_plain_template_occurrences(item)


def _named_params_from_plain_template(kind: str, args) -> set[str]:
    """Extract named-parameter keys from a plain template representation."""
    names: set[str] = set()
    if kind == "stmpl":
        for arg in args:
            if not isinstance(arg, str) or "=" not in arg:
                continue
            name, _value = arg.split("=", 1)
            if name:
                names.add(name)
        return names

    if kind == "tmpl":
        for arg_node in args:
            if not (isinstance(arg_node, list) and arg_node):
                continue
            first = arg_node[0]
            if not (isinstance(first, str) and "=" in first):
                continue
            name, _value = first.split("=", 1)
            if name:
                names.add(name)
        return names

    assert False, f"unexpected template kind: {kind!r}"


def _iter_plain_dict_nodes(node):
    """Yield every dict node reachable from a plain corpus node tree."""
    if isinstance(node, dict):
        yield node
        for value in node.values():
            yield from _iter_plain_dict_nodes(value)
        return
    if isinstance(node, list):
        for item in node:
            yield from _iter_plain_dict_nodes(item)


def _plain_node_kind(node: dict) -> str:
    """Return the single plain node kind encoded by node."""
    keys = [key for key in ["stmpl", "tmpl", "custom_tag"] if key in node]
    assert (
        len(keys) == 1
    ), f"plain node must have exactly one representation key: {node!r}"
    return keys[0]


def _validate_plain_tmpl_tree_node(node, *, allowed_node_types: frozenset[str]) -> None:
    """Validate recursive shape of a plain tmpl parse-tree node."""
    assert isinstance(node, dict), f"tmpl node must be a dict: {node!r}"
    assert _plain_node_kind(node) == "tmpl", f"expected tmpl node, got: {node!r}"

    tree = node["tmpl"]
    assert (
        isinstance(tree, list) and tree
    ), f"tmpl payload must be a non-empty list: {node!r}"
    for segment in tree:
        assert (
            isinstance(segment, list) and segment
        ), f"tmpl segments must be non-empty lists: {segment!r}"
        for item in segment:
            if isinstance(item, str):
                assert (
                    "string" in allowed_node_types
                ), f"string segment item not allowed by claim: {item!r}"
                continue
            assert isinstance(
                item, dict
            ), f"tmpl segment item must be str or dict: {item!r}"
            kind = _plain_node_kind(item)
            assert (
                kind in allowed_node_types
            ), f"tmpl nested node kind {kind!r} not allowed by claim"
            if kind == "tmpl":
                _validate_plain_tmpl_tree_node(
                    item, allowed_node_types=allowed_node_types
                )


def _parse_plain_special_kq_stmpl(stmpl: str) -> tuple[str, str, str]:
    """Parse a plain מ:כו״ק מיוחד stmpl into ketiv, qere, and sug."""
    stmpl = stmpl.translate(_NORM_QUOTES)
    prefix = "מ:כו״ק מיוחד|"
    assert stmpl.startswith(prefix), f"not a special-kq stmpl: {stmpl!r}"
    body = stmpl[len(prefix) :]
    assert "|סוג=" in body, f"special-kq stmpl missing סוג=: {stmpl!r}"
    positional_part, sug = body.rsplit("|סוג=", 1)
    assert sug, f"special-kq stmpl has empty סוג=: {stmpl!r}"
    assert (
        "|" in positional_part
    ), f"special-kq stmpl must contain two positional params before סוג=: {stmpl!r}"
    ketiv, qere = positional_part.split("|", 1)
    assert ketiv, f"special-kq stmpl missing ketiv param: {stmpl!r}"
    assert qere, f"special-kq stmpl missing qere param: {stmpl!r}"
    return ketiv, qere, sug


def _verify_template_set_plain_observed(
    record: ClaimRecord, ctx: Context, *, key: str = "templates"
) -> None:
    """Assert that every declared template appears in the plain corpus survey.

    key: the record.data key holding the name(s). If the value is a list,
    every element is checked. If it is a string, it is wrapped in a list first.
    """
    declared_raw = record.data[key]
    if isinstance(declared_raw, list):
        declared = frozenset(declared_raw)
    else:
        declared = frozenset([declared_raw])
    observed = survey_artifact.template_names_observed(ctx.survey_plain)
    missing = declared - observed
    assert (
        not missing
    ), f"declared templates not found in plain corpus survey: {sorted(missing)}"


