def verify_mp_plain_verse_d_col_named_params(record: ClaimRecord, ctx: Context) -> None:
    """D-column verse-label templates use only the declared named-parameter keys."""
    label_template = record.data["label_template"]
    allowed_named_params = frozenset(record.data["allowed_named_params"])
    always_present = bool(record.data.get("always_present", False))
    pseudo_keys = frozenset(["0", "תתת"])

    observed_named_params: set[str] = set()
    for book39, ch_key, v_key, verse in iter_plain_verses(ctx.corpus_plain):
        d_col = verse[1]
        assert isinstance(d_col, list), f"D column is not a list: {d_col!r}"

        if v_key in pseudo_keys:
            assert d_col == [], (
                f"book39={book39['book24_name']!r} ch={ch_key} v={v_key}:"
                f" pseudo-verse D column should be empty, got {d_col!r}"
            )
            continue

        if always_present:
            assert len(d_col) == 1, (
                f"book39={book39['book24_name']!r} ch={ch_key} v={v_key}:"
                f" expected one D-column item, got {len(d_col)}"
            )

        label_occurrences = []
        for item in d_col:
            for kind, tmpl_name, args in _iter_plain_template_occurrences(item):
                if tmpl_name.translate(_NORM_QUOTES) == label_template.translate(
                    _NORM_QUOTES
                ):
                    label_occurrences.append((kind, args))

        if always_present:
            assert len(label_occurrences) == 1, (
                f"book39={book39['book24_name']!r} ch={ch_key} v={v_key}:"
                f" expected exactly one {label_template!r} template in D,"
                f" found {len(label_occurrences)}"
            )
        elif not label_occurrences:
            continue

        kind, args = label_occurrences[0]
        named_params = _named_params_from_plain_template(kind, args)
        observed_named_params.update(named_params)
        unexpected = named_params - allowed_named_params
        assert not unexpected, (
            f"book39={book39['book24_name']!r} ch={ch_key} v={v_key}:"
            f" unexpected D-label named params {sorted(unexpected)}"
            f" (allowed {sorted(allowed_named_params)})"
        )

    assert observed_named_params <= allowed_named_params, (
        f"observed named params {sorted(observed_named_params)} exceed allowed"
        f" {sorted(allowed_named_params)}"
    )


def verify_mp_plain_verse_e_col_semantics(record: ClaimRecord, ctx: Context) -> None:
    """E column is a segmented sequence of strings and plain template/custom-tag objects.

    Checks: (1) every item is of a declared type, (2) all declared types are observed,
    and (3) tmpl nodes satisfy the recursive tmpl-tree grammar.
    """
    allowed_types = frozenset(record.data["element_types"])
    assert allowed_types == frozenset(
        ["string", "stmpl", "tmpl", "custom_tag"]
    ), f"unexpected claim element_types: {sorted(allowed_types)}"
    observed_types: set[str] = set()
    for _book39, _ch_key, _v_key, verse in iter_plain_verses(ctx.corpus_plain):
        e_col = verse[2]
        assert isinstance(e_col, list), f"E column is not a list: {e_col!r}"
        for item in e_col:
            if isinstance(item, str):
                observed_types.add("string")
                continue
            assert isinstance(
                item, dict
            ), f"unexpected E-column item type: {type(item).__name__}"
            kind = _plain_node_kind(item)
            observed_types.add(kind)
            assert kind in allowed_types, (
                f"unexpected E-column node kind {kind!r};"
                f" allowed kinds are {sorted(allowed_types)}"
            )
            if kind == "tmpl":
                _validate_plain_tmpl_tree_node(
                    item, allowed_node_types=frozenset(["string", "stmpl", "tmpl"])
                )
    assert observed_types == allowed_types, (
        f"E-column observed types {sorted(observed_types)}"
        f" != declared {sorted(allowed_types)}"
    )


def verify_mp_plain_docs_custom_tag_keys_and_values(
    record: ClaimRecord, ctx: Context
) -> None:
    """Plain custom_tag nodes use only the documented key and allowed tag values."""
    key_name = record.data["key"]
    allowed_values = frozenset(record.data["allowed_values"])
    allowed_prefixes = tuple(record.data.get("allowed_prefixes", []))
    observed_values: set[str] = set()

    for _book39, _ch_key, _v_key, verse in iter_plain_verses(ctx.corpus_plain):
        for col in verse:
            for node in _iter_plain_dict_nodes(col):
                if key_name not in node:
                    continue
                assert frozenset(node.keys()) == frozenset(
                    [key_name]
                ), f"custom_tag node has unexpected extra keys: {node!r}"
                value = node[key_name]
                assert (
                    isinstance(value, str) and value
                ), f"custom_tag value must be a non-empty string: {node!r}"
                observed_values.add(value)
                is_allowed = value in allowed_values or any(
                    value.startswith(prefix) for prefix in allowed_prefixes
                )
                assert is_allowed, (
                    f"unexpected custom_tag value {value!r};"
                    f" allowed values are {sorted(allowed_values)}"
                    f" and allowed prefixes are {list(allowed_prefixes)!r}"
                )

    missing_exact = allowed_values - observed_values
    assert (
        not missing_exact
    ), f"declared exact custom_tag values not observed: {sorted(missing_exact)}"


