def verify_mp_plain_kq_special_semantic_shape(
    record: ClaimRecord, ctx: Context
) -> None:
    """Plain special-kq entries carry ketiv, qere, and a declared subtype value."""
    template_name = record.data["template"]
    required_named_params = frozenset(record.data["required_named_params"])
    assert (
        ctx.claim_records is not None
    ), "ctx.claim_records was not provided to verifier context"
    subtype_claim = ctx.claim_records["mp.both.templates.kq-special.subtypes"]
    allowed_sug_values = frozenset(
        value.translate(_NORM_QUOTES) for value in subtype_claim.data["values"]
    )

    saw_special_kq = False
    for _book39, _ch_key, _v_key, verse in iter_plain_verses(ctx.corpus_plain):
        for col in verse:
            for node in _iter_plain_dict_nodes(col):
                stmpl = node.get("stmpl")
                if not (
                    isinstance(stmpl, str)
                    and stmpl.translate(_NORM_QUOTES).startswith(
                        template_name.translate(_NORM_QUOTES) + "|"
                    )
                ):
                    continue
                saw_special_kq = True
                ketiv, qere, sug = _parse_plain_special_kq_stmpl(stmpl)
                assert (
                    ketiv and qere
                ), f"special-kq stmpl missing ketiv/qere content: {stmpl!r}"
                assert (
                    sug.translate(_NORM_QUOTES) in allowed_sug_values
                ), f"unexpected special-kq סוג= value {sug!r}"
                assert required_named_params == frozenset(
                    ["סוג"]
                ), f"unexpected required named params declaration: {sorted(required_named_params)}"
    assert saw_special_kq, f"no plain {template_name!r} stmpl instances observed"


def verify_mp_plain_docs_plain_only_templates_categories(
    record: ClaimRecord, ctx: Context
) -> None:
    """Plain-only templates are partitioned into exactly one declared category."""
    categories = record.data["categories"]
    assert (
        isinstance(categories, list) and categories
    ), "categories must be a non-empty list"

    declared_names = [row["name"] for row in categories]
    assert len(declared_names) == len(
        set(declared_names)
    ), f"duplicate category names in claim data: {declared_names}"

    # Ensure claim data matches the source-of-truth category defs used by authored docs.
    expected_categories = [
        {
            "name": category_name,
            "templates": list(templates),
        }
        for category_name, templates in cmn.PLAIN_ONLY_CATEGORY_DEFS
    ]
    assert (
        categories == expected_categories
    ), "categories claim data drifted from source defs"

    all_templates: list[str] = []
    for category in categories:
        templates = category["templates"]
        assert isinstance(
            templates, list
        ), f"category {category['name']!r} templates must be a list"
        all_templates.extend(templates)

    assert len(all_templates) == len(
        set(all_templates)
    ), "a template appears in more than one declared plain-only category"

    declared_set = frozenset(all_templates)
    assert declared_set == cmn.PLAIN_ONLY_TEMPLATE_SET, (
        f"declared plain-only template set {sorted(declared_set)}"
        f" != source-of-truth {sorted(cmn.PLAIN_ONLY_TEMPLATE_SET)}"
    )

    # Every declared plain-only template should be observed in plain and absent from plus.
    observed_plain = survey_artifact.template_names_observed(ctx.survey_plain)
    observed_plus = survey_artifact.template_names_observed(ctx.survey)
    missing_from_plain = declared_set - observed_plain
    present_in_plus = declared_set & observed_plus
    assert (
        not missing_from_plain
    ), f"declared plain-only templates missing from plain survey: {sorted(missing_from_plain)}"
    assert (
        not present_in_plus
    ), f"declared plain-only templates unexpectedly present in plus survey: {sorted(present_in_plus)}"


def verify_mp_plain_docs_plain_only_templates_pre_evaluated_handlers(
    record: ClaimRecord, ctx: Context
) -> None:
    """Pre-evaluated plain-only handler behavior matches declared source mappings."""
    del ctx  # This verifier checks declared/source mappings, not corpus shape.

    source_module = record.data["source_module"]
    assert (
        source_module == "mpplus_boring_tmpls.py"
    ), f"unexpected source_module in claim data: {source_module!r}"

    declared = record.data["handler_behavior"]
    assert (
        isinstance(declared, dict) and declared
    ), "handler_behavior must be a non-empty dict"

    expected = dict(cmn.PLAIN_ONLY_PRE_EVALUATED_HANDLER_BEHAVIOR)
    assert (
        declared == expected
    ), "handler_behavior claim data drifted from source-of-truth"

    # Contract: handler_behavior covers exactly the pre-evaluated plain-only category.
    declared_templates = frozenset(declared.keys())
    expected_templates = frozenset(cmn.PLAIN_ONLY_PRE_EVALUATED_TEMPLATES)
    assert declared_templates == expected_templates, (
        f"handler_behavior keys {sorted(declared_templates)}"
        f" != pre-evaluated template set {sorted(expected_templates)}"
    )

    # Keep behavior labels constrained so docs/verifiers remain machine-checkable.
    allowed_behavior_labels = frozenset(
        [
            "_just_take_arg_1",
            "_handle_accent",
            "_handle_qupo",
            "_handle_pseudo_title",
            "_handle_word_with_puncta_extraordinaria",
            "constant replacement",
            "constant empty string",
        ]
    )
    unknown = set(declared.values()) - allowed_behavior_labels
    assert not unknown, f"unknown handler behavior label(s): {sorted(unknown)}"


